import re
import numpy as np
import matplotlib.pyplot as plt

# Read the log file
def read_log_file(file_path):
    with open(file_path, 'r') as file:
        data = file.readlines()
    return data

# Extract temperature and volume data
def extract_data(log_data):
    temperature = []
    volume = []
    for line in log_data:
        match = re.match(r"\s*(\d+)\s+([\d.]+)\s+[-\d.]+\s+[-\d.]+\s+[-\d.]+\s+[-\d.]+\s+([\d.]+)", line)
        if match:
            temperature.append(float(match.group(2)))
            volume.append(float(match.group(3)))
    return np.array(temperature), np.array(volume)

# Calculate the derivative of volume with respect to temperature
def calculate_derivative(temperature, volume):
    return np.gradient(volume, temperature)

# Detect the glass transition temperature
def detect_glass_transition(temperature, derivative):
    # Find the point where the derivative changes significantly
    change_points = np.where(np.abs(np.diff(derivative)) > np.std(derivative))[0]
    if len(change_points) > 0:
        return temperature[change_points[0]]
    return None

# Main function
def main():
    log_file_path = "/results/6_Nov_Optimised/gpt_4o/react/quenching/subtask_true/level_1/brief/sio2_quenching_1_subtask_quenching_trial_2/quenching.log"
    log_data = read_log_file(log_file_path)
    temperature, volume = extract_data(log_data)
    derivative = calculate_derivative(temperature, volume)
    tg = detect_glass_transition(temperature, derivative)
    if tg:
        print(f"Glass transition temperature (Tg): {tg:.2f}")
    else:
        print("Glass transition temperature not detected.")

if __name__ == "__main__":
    main()
